import type { FormulaNote } from "./types";

export const analysisNotes: Record<string, FormulaNote> = {
  "ra-supremum": {
    notation: "sup A is the supremum of the set A. The braces hold the set of all real numbers M that are upper bounds. a ≤ M for every a in A is the test for being an upper bound. min means the least element of that set of bounds.",
    proof: "Call a real M an upper bound of A when a ≤ M for every a in A. The set in braces is exactly the set of those bounds. The least upper bound is, by the meaning of “least,” the minimum of that set. So the equality is the definition of sup A, once that minimum exists. In the reals it does exist whenever A is nonempty and bounded above: that is the least-upper-bound property. The minimum need not lie in A. It lies in A exactly when A has a greatest element.",
  },
  "ra-sequence-limit": {
    notation: "∀ means “for every” and ∃ means “there exists.” ε is a positive tolerance. N is an index. n ≥ N restricts attention to the tail. |aₙ − L| is the distance from the n-th term to L.",
    proof: "Suppose the sentence holds, and draw any window of radius ε around L. The N it supplies puts every later term inside that window. That is what it means for the terms to approach L. Conversely, if every such window eventually traps the whole tail, the sentence is true. The order of the quantifiers is the whole content: ε is chosen first, and N may depend on it. The limit is unique. If the terms also approach M, then |L − M| ≤ |L − aₙ| + |aₙ − M| can be made smaller than any positive number, so L = M.",
  },
  "ra-cauchy": {
    notation: "ε is a positive tolerance. N is an index. m and n are any two indices from that stage on. |aₘ − aₙ| is the distance between two terms, with no limit named.",
    proof: "The sentence says the terms become close to each other: every tolerance is eventually respected by every pair in the tail. If aₙ → L, this follows. Given ε, choose N so that n ≥ N implies |aₙ − L| < ε/2. Then for m, n ≥ N, |aₘ − aₙ| ≤ |aₘ − L| + |aₙ − L| < ε. In the reals the converse is true as well. A Cauchy sequence is bounded, so Bolzano–Weierstrass supplies a convergent subsequence aₙₖ → L. The Cauchy condition then pulls every term toward that same L: far enough out, a term is close to a subsequence term, which is close to L. In the rationals the converse fails, because the limit may be the hole the terms are huddling over.",
  },
  "ra-absolute": {
    notation: "∑ |aₙ| is the series of absolute values. < ∞ says that series of nonnegative terms converges. The arrow says this forces the signed series ∑ aₙ to converge.",
    proof: "Let sₙ be the partial sums of ∑ aₙ and tₙ the partial sums of ∑ |aₙ|. For m > n, |sₘ − sₙ| = |∑_{k=n+1}^{m} aₖ| ≤ ∑_{k=n+1}^{m} |aₖ| = tₘ − tₙ. If ∑ |aₙ| converges, the sequence (tₙ) is Cauchy, so the right side is small for large n, and (sₙ) is Cauchy. A Cauchy sequence of reals converges, so ∑ aₙ converges. The comparison uses the triangle inequality, and the last step uses completeness. The converse is false: the alternating harmonic series converges, while its absolute series is the harmonic series and diverges.",
  },
  "ra-power-series": {
    notation: "R is the radius of convergence. lim sup is the limit superior, the largest limit point of the sequence. |cₙ|^{1/n} is the n-th root of the absolute value of the coefficient. 1/R is ordinary division, with the conventions 1/0 = ∞ and 1/∞ = 0.",
    proof: "Let L = lim sup |cₙ|^{1/n}. For the series ∑ cₙ (x − a)ⁿ, the root test looks at |cₙ (x − a)ⁿ|^{1/n} = |cₙ|^{1/n} |x − a|, whose limit superior is L |x − a|. The root test says the series converges absolutely when that number is less than 1 and diverges when it is greater than 1. Therefore the series converges for |x − a| < 1/L and diverges for |x − a| > 1/L, when L is positive and finite. That says the radius is R = 1/L. If L = 0 the series converges for every x, so R = ∞. If L = ∞ it converges only at the center, so R = 0. In every case 1/R = L.",
  },
  "ra-epsilon-delta": {
    notation: "ε is the output tolerance and δ the input tolerance, both required to be positive. 0 < |x − a| says x is within δ of a but is not a itself. |f(x) − L| is the distance from the output to L. The quantifiers are ordered: ε first, then δ.",
    proof: "The sentence is the definition of lim_{x→a} f(x) = L. To see that it says the outputs approach L: whoever challenges you with a tolerance ε must be answered with a δ that keeps every nearby output, other than possibly at a itself, inside the ε-window. If some ε has no such δ, then there are inputs arbitrarily close to a whose outputs stay at least ε away from L, and the limit is not L. The exclusion of x = a is written into 0 < |x − a|. Changing f(a), or leaving f(a) undefined, does not change the truth of the sentence.",
  },
  "ra-continuity": {
    notation: "lim_{x→a} is the two-sided limit. f(x) is the output at a nearby input. f(a) is the value actually attained at a. The equality says those two numbers agree.",
    proof: "By the epsilon-delta definition, the limit equality says: for every ε > 0 there is a δ > 0 such that 0 < |x − a| < δ implies |f(x) − f(a)| < ε. At x = a the distance |f(a) − f(a)| is 0, which is already less than ε. So the same δ works with the restriction weakened to |x − a| < δ. That is the epsilon-delta definition of continuity at a, and it requires f(a) to exist. Conversely, a function continuous at a in that sense has limit f(a) there. A limit can exist where the function is undefined; continuity cannot.",
  },
  "ra-uniform-continuity": {
    notation: "ε is the output tolerance and δ the input tolerance. The pair x, y ranges over the whole set S, not over a neighborhood of one point. |x − y| < δ is the same δ for every pair. |f(x) − f(y)| is the distance between outputs.",
    proof: "The sentence says one δ, chosen from ε alone, works simultaneously for every pair of points in S. That is the definition of uniform continuity on S. It implies ordinary continuity at each point: fix y, and the same δ serves as the pointwise δ at y. The converse fails. On (0, 1), f(x) = 1/x is continuous, but the δ that controls the outputs near 0 must shrink as the point approaches 0, so no single δ serves the whole interval. On a closed bounded interval the converse returns: a continuous real function is uniformly continuous, because an open cover by the pointwise δ-neighborhoods has a finite subcover and a Lebesgue number that serves as the uniform δ.",
  },
  "ra-derivative": {
    notation: "f'(a) is the derivative at a. h is the input step, sent to 0 but not equal to 0 inside the fraction. The numerator is the change in output. The fraction is the slope of the secant through a and a + h.",
    proof: "The difference quotient is the slope between (a, f(a)) and (a + h, f(a + h)), by the two-point formula for slope. The derivative is defined to be the limit of those slopes as h → 0 through nonzero values. For f(x) = x², the quotient at a is (2ah + h²)/h = 2a + h for h ≠ 0, whose limit is 2a. Setting h = 0 before canceling divides by zero and is not the limit. If the left-hand and right-hand limits of the quotient differ, as they do for |x| at 0, the two-sided derivative does not exist.",
  },
  "ra-mvt": {
    notation: "f'(c) is the derivative at an interior point c. f(b) − f(a) is the change in output over the interval. b − a is the change in input. The right side is the slope of the chord from a to b.",
    proof: "Assume f is continuous on [a, b] and differentiable on (a, b). Define g(x) = f(x) − f(a) − ((f(b) − f(a))/(b − a))(x − a). Then g(a) = g(b) = 0, and g is continuous on the closed interval and differentiable on the open interval. A continuous function on a closed bounded interval attains its maximum and minimum. If both occur at the endpoints, g is identically 0 and g' is 0 everywhere. Otherwise an extremum occurs at some c in (a, b), and there g'(c) = 0, because a nonzero derivative would push the function both above and below the extremal value. Differentiating g gives g'(c) = f'(c) − (f(b) − f(a))/(b − a). So f'(c) equals the chord slope.",
  },
  "ra-taylor": {
    notation: "Rₙ(x) is the remainder after the degree-n Taylor polynomial at a. f^{(n+1)} is the (n+1)-st derivative. ξ is some point between a and x. (n+1)! is the factorial. (x − a)^{n+1} is the power of the distance from the center.",
    proof: "Fix x and write the remainder as f(x) − ∑_{k=0}^{n} f^{(k)}(a)(x − a)^k / k!. Define φ(t) = f(x) − ∑_{k=0}^{n} f^{(k)}(t)(x − t)^k / k! − K (x − t)^{n+1}, and choose K so that φ(a) = 0. Then φ(x) = 0 as well. Rolle’s theorem, applied n + 1 times to the successive derivatives, produces a point ξ between a and x with φ^{(n+1)}(ξ) = 0. Differentiating the sum telescopes: each term’s derivative cancels the next, and φ^{(n+1)}(t) = f^{(n+1)}(t) − K (n+1)!. Setting this to 0 at ξ gives K = f^{(n+1)}(ξ)/(n+1)!. Therefore the remainder is exactly K (x − a)^{n+1}.",
  },
  "ra-riemann": {
    notation: "The overline marks the upper integral, the infimum of upper sums. The underline marks the lower integral, the supremum of lower sums. f is a bounded function on [a, b]. Equality of the two is the claim.",
    proof: "For a partition, the upper sum uses the supremum of f on each piece and the lower sum uses the infimum. Every lower sum is at most every upper sum, so the supremum of the lower sums is at most the infimum of the upper sums. The function is defined to be Riemann integrable when those two numbers are equal, and the common value is the integral. Equivalently, for every ε > 0 some partition has upper sum minus lower sum less than ε: the gap between upper and lower integral is the infimum of those differences, so the gap vanishes exactly when the differences can be made arbitrarily small. A bounded function with finitely many discontinuities meets the test. The characteristic function of the rationals does not: every upper sum is the length of the interval and every lower sum is 0.",
  },
  "ra-ftc": {
    notation: "d/dx differentiates with respect to the upper limit x. The integral from a to x builds a function of that upper limit. G' is the derivative of G. G(b) − G(a) evaluates it at the ends. The two equations are the two halves of the theorem.",
    proof: "Let f be continuous and set F(x) = ∫_a^x f. For h ≠ 0 the difference quotient is the average (1/h) ∫_x^{x+h} f. By continuity, on a short interval every value of f is within ε of f(x), so the average is within ε of f(x). Thus F'(x) = f(x). For the second equation, let G be any antiderivative of an integrable derivative G', and set F(x) = ∫_a^x G'. Then F' = G', so (G − F)' = 0 and G − F is constant. Also F(a) = 0. Therefore G(b) − G(a) = F(b) − F(a) = ∫_a^b G'.",
  },
  "ra-uniform-convergence": {
    notation: "sup is the supremum over every x in S. |fₙ(x) − f(x)| is the pointwise error. The arrow says that worst-case error tends to 0 as n grows. One n has to work for the whole set.",
    proof: "The displayed limit is the definition of uniform convergence on S: the largest error on S becomes small, so the same stage works at every point. It implies pointwise convergence, because the error at any single x is at most the supremum. The converse is false. On (0, 1), fₙ(x) = xⁿ converges pointwise to 0, but the supremum of xⁿ on (0, 1) is 1 for every n, so the convergence is not uniform. Uniform convergence preserves continuity: if each fₙ is continuous and the convergence is uniform, the limit is continuous, because the uniform error adds a small amount to the ε/3 estimate from one of the continuous functions.",
  },
  "ra-cantor": {
    notation: "m(C) is the Lebesgue measure, the total length, of the middle-thirds Cantor set. The sum adds the lengths removed at each stage. 2^{n−1} is the number of open intervals removed at stage n. 3ⁿ is the denominator of each such length. The last equality says the whole sum equals 1.",
    proof: "Start with [0, 1], of length 1. At stage 1 remove the middle third, one interval of length 1/3. At stage n remove 2^{n−1} open intervals, each of length 1/3ⁿ. The total length removed is ∑_{n=1}^{∞} 2^{n−1}/3ⁿ. Factor out 1/3: the sum is (1/3) ∑_{n=0}^{∞} (2/3)ⁿ = (1/3) / (1 − 2/3) = 1. The Cantor set is what remains, so its measure is 1 − 1 = 0. The set is not empty. The endpoints of every removed interval stay in, and in ternary expansions it contains every number in [0, 1] whose expansion uses only the digits 0 and 2.",
  },
  "cx-holomorphic": {
    notation: "f'(z₀) is the complex derivative at z₀. h is a complex step, approaching 0 through values in the plane, not along a line. The fraction is the difference quotient. The limit has to exist as a single complex number.",
    proof: "The equality is the definition of complex differentiability at z₀: the difference quotient approaches one complex value no matter how h approaches 0 in the plane. That is strictly stronger than the existence of the two real partial derivatives. If the quotient approaches L along every path, it approaches L along the real direction and along the imaginary direction, and those two limits agree. Writing f = u + iv and equating them produces the Cauchy–Riemann equations. If the limit fails along even one path, or two paths disagree, f'(z₀) does not exist. The function conjugate(z) fails: the quotient is 1 along the real axis and −1 along the imaginary axis.",
  },
  "cx-cauchy-riemann": {
    notation: "u and v are the real and imaginary parts of f, so f = u + iv. A subscript x or y is a partial derivative. The two equations are both required.",
    proof: "Suppose f'(z) exists at z = x + iy. Along real h the difference quotient tends to u_x + i v_x. Along imaginary steps ik, the quotient is [u(x, y+k) − u + i(v(x, y+k) − v)] / (ik). Since 1/i = −i, the limit is v_y − i u_y. The two paths must agree, so u_x + i v_x = v_y − i u_y. Equating real and imaginary parts gives u_x = v_y and v_x = −u_y, which is the second displayed equation written as u_y = −v_x. The equations are necessary. With continuous partials they are also sufficient for complex differentiability, by a first-order real approximation that the equations turn into multiplication by a single complex number.",
  },
  "cx-contour": {
    notation: "∫_γ f is the contour integral of f along the path γ. On the right, γ(t) for t from a to b parametrizes the path. γ'(t) is the velocity. dt marks an ordinary real integral.",
    proof: "Partition [a, b]. The contour sum adds f at a sample point on each piece of the path, times the complex displacement of that piece. If γ is continuously differentiable, the displacement γ(tⱼ) − γ(tⱼ₋₁) equals γ'(tⱼ) Δt plus a smaller error. The sums therefore approach ∫_a^b f(γ(t)) γ'(t) dt. That common limit is the definition of ∫_γ f. A reparametrization replaces γ(t) by γ(φ(s)) and multiplies the velocity by φ'(s). The chain rule and the substitution rule cancel, so the integral depends on the oriented path and not on the speed of the parametrization. Reversing orientation changes the sign.",
  },
  "cx-cauchy-theorem": {
    notation: "The circle on the integral sign means γ is a simple closed curve, traversed once. f is the integrand. The claim is that the integral equals the complex number 0.",
    proof: "Take f holomorphic inside and on a triangle. If the integral over the triangle had absolute value at least some positive number, divide the triangle into four congruent triangles by joining the midpoints. At least one smaller triangle carries at least a quarter of the integral. Repeat. The triangles shrink to a point z₀, where f(z) = f(z₀) + f'(z₀)(z − z₀) + ε(z)(z − z₀) with ε(z) → 0. The integral of the constant and of (z − z₀) over a closed triangle is zero, because both have antiderivatives. The ε term, on a triangle of diameter d and perimeter p, is at most (max |ε|) d p in absolute value. At stage n both d and p have been multiplied by 1/2, while the integral was multiplied by at least 1/4 at each selection, and max |ε| → 0. The only number compatible with the estimate is 0. A square, a disk, and a convex contour reduce to triangles by subdivision, and the interior edges cancel.",
  },
  "cx-cif": {
    notation: "f(a) is the value at an interior point a. 2πi is the constant from one positive loop around 0. The integrand is f(z) divided by z − a. γ is a simple closed curve winding once positively around a, with f holomorphic inside and on γ.",
    proof: "Write f(z)/(z − a) = f(a)/(z − a) + (f(z) − f(a))/(z − a). The integral of the first piece, parametrize a small circle z = a + re^{it}, is f(a) times ∫_0^{2π} (ire^{it})/(re^{it}) dt = f(a) · 2πi. Cauchy's theorem lets the original contour be replaced by that small circle, because the integrand is holomorphic in between. On the small circle, continuity of f makes |f(z) − f(a)| < ε, so the second integral has absolute value at most (1) · ε/r · 2πr = 2πε. It can be made arbitrarily small, so it is 0. Therefore ∮ f(z)/(z − a) dz = 2πi f(a). Divide by 2πi.",
  },
  "cx-liouville": {
    notation: "|f'(a)| is the modulus of the derivative at a. The maximum is the largest modulus of f on the circle of radius R centered at a. Dividing by R scales that maximum.",
    proof: "Differentiate under the Cauchy integral formula, or apply the formula to (f(z) − f(a))/(z − a) and pass to the limit. The result is f'(a) = (1/(2πi)) ∮_{|z−a|=R} f(z)/(z − a)² dz. On that circle |z − a| = R, so |f(z)/(z − a)²| ≤ M/R² where M is the maximum of |f|. The length of the circle is 2πR. The standard length estimate gives |f'(a)| ≤ (1/(2π)) · (M/R²) · 2πR = M/R. That is the displayed bound. It is an estimate at one point. Liouville's theorem is the corollary: if f is entire and |f| is bounded by M everywhere, let R → ∞ to get f'(a) = 0 for every a, so f is constant.",
  },
  "cx-laurent": {
    notation: "The sum runs over every integer power, positive and negative. cₙ is the coefficient of (z − a)ⁿ. c₋₁ is the coefficient of 1/(z − a). Res(f, a) is the residue of f at a.",
    proof: "In an annulus around a where f is holomorphic, draw two circles, the outer one positively oriented and the inner one negatively oriented. Cauchy's theorem on the cut annulus gives f(z) as (1/(2πi)) times the integral of f(w)/(w − z) over those two circles. Expand 1/(w − z) as a geometric series in (z − a)/(w − a) on the outer circle and in (w − a)/(z − a) on the inner circle. Integrating term by term produces ∑ cₙ (z − a)ⁿ with cₙ = (1/(2πi)) ∮ f(w)/(w − a)^{n+1} dw. For n = −1 the integrand is f itself, so c₋₁ = (1/(2πi)) ∮ f. The residue is defined to be that coefficient, the unique one that survives in the integral of the series over a small positive circle. Hence c₋₁ = Res(f, a).",
  },
  "cx-residue": {
    notation: "The integral is over a simple closed curve γ, positively oriented. The sum runs over the singularities aₖ of f inside γ, finitely many, and none on γ. Res(f, aₖ) is the coefficient of 1/(z − aₖ) in the Laurent series at aₖ. 2πi is the constant from one full turn.",
    proof: "Around each aₖ draw a small circle, small enough that the circles lie inside γ and do not meet. On the region between γ and these circles, f is holomorphic. Cauchy's theorem says the integral over γ, minus the integrals over the small circles, is 0. Each small circle contributes ∮ f = 2πi c₋₁ = 2πi Res(f, aₖ), by the Laurent expansion and the vanishing of every other power’s integral. Therefore the integral over γ equals 2πi times the sum of the residues inside. A pole where the Laurent series has only finitely many negative powers is included: only c₋₁ enters the sum.",
  },
  "cx-argument": {
    notation: "f'/f is the logarithmic derivative. The integral is over a simple closed curve on which f has no zero or pole. Z is the number of zeros inside, counted with multiplicity. P is the number of poles inside, counted with order. The quotient Z − P is an integer.",
    proof: "Near a zero of order m, f(z) = (z − a)^m g(z) with g holomorphic and g(a) ≠ 0. Then f'/f = m/(z − a) + g'/g, and g'/g is holomorphic there. The residue of f'/f at a is m. Near a pole of order p, the same calculation with m replaced by −p gives residue −p. Residues add, so the sum of the residues of f'/f inside γ is Z − P. The residue theorem multiplies that sum by 2πi. Dividing by 2πi produces the displayed count. Each simple zero contributes 1 and each simple pole contributes −1. A zero on the contour is excluded: f'/f would not be continuous there.",
  },
  "cx-conformal": {
    notation: "f'(z₀) is the complex derivative at z₀. ≠ 0 says it is a nonzero complex number. The conclusion is that curves through z₀ have their oriented angles preserved by f.",
    proof: "Let two curves pass through z₀ with nonzero tangent vectors v and w. Their images have tangents f'(z₀) v and f'(z₀) w, by the chain rule. Multiplication by the nonzero complex number f'(z₀) multiplies every tangent by the same positive scale |f'(z₀)| and adds the same argument arg f'(z₀). The difference of arguments, which is the oriented angle from v to w, is unchanged. If f'(z₀) = 0 the two tangents can be crushed differently. The map z ↦ z² doubles angles at 0, where the derivative vanishes, and preserves them everywhere else.",
  },
  "mp-measure": {
    notation: "μ is a measure. The union runs over a sequence of measurable sets. The hypothesis, required for this equality and not printed as a symbol, is that the sets are pairwise disjoint. The right side adds their measures, allowing the value ∞.",
    proof: "Countable additivity on disjoint measurable sets is part of the definition of a measure, together with μ taking values in [0, ∞] and μ(∅) = 0. Finite additivity is the special case in which all but finitely many sets are empty. For Lebesgue measure the equality is a theorem, not only a name. The length of a union of disjoint intervals is the sum of the lengths. Carathéodory’s criterion selects the measurable sets, and the outer measure restricted to them stays countably additive: the inequality ≤ is subadditivity of outer measure, and ≥ comes from cutting the sets apart with disjoint measurable covers. Without disjointness the equality fails. Two copies of the same set of measure 1 have union of measure 1 and sum of measures 2.",
  },
  "mp-measurable-fn": {
    notation: "{x : f(x) > a} is the set of points where the function exceeds the height a. Σ is the sigma-algebra of measurable sets. The condition is required for every real height a.",
    proof: "The displayed line is the definition of a measurable real function on (X, Σ). It generates the other level sets. The set where f ≥ a is the intersection over n of the sets where f > a − 1/n, and a sigma-algebra is closed under countable intersections. The set where f ≤ a is the complement of the set where f > a. The set where f < a is a countable union of sets where f ≤ a − 1/n. So one family of tests gives all four. A continuous function on the reals meets the test because {f > a} is open, hence Borel. The point of the definition is that f^{−1} of a Borel set is measurable, which follows by showing that the sets whose preimages are measurable form a sigma-algebra containing the rays (a, ∞).",
  },
  "mp-integral": {
    notation: "The left side is the integral of a nonnegative measurable function against μ. On the right, μ{f > t} is the measure of the set where f exceeds the height t. The integral in t is an ordinary integral over the heights from 0 to ∞.",
    proof: "For each x, the value f(x) equals ∫_0^{∞} 1_{t < f(x)} dt, the length of the interval of heights below f(x). Integrate both sides in x. The integrand is nonnegative, so Tonelli’s theorem allows the integrals to be swapped: ∫ f dμ = ∫_0^{∞} (∫ 1_{f > t} dμ) dt = ∫_0^{∞} μ{f > t} dt. No extra constant appears. The same identity is why the expectation of a nonnegative random variable is ∫_0^{∞} P(X > t) dt.",
  },
  "mp-mct": {
    notation: "0 ≤ fₙ says each function is nonnegative. The arrow fₙ ↑ f says the sequence increases pointwise to f. The integrals are claimed to increase to the integral of the limit, which may be ∞.",
    proof: "Since 0 ≤ fₙ ≤ fₙ₊₁ ≤ f, the integrals form an increasing sequence bounded above by ∫ f, so they approach some limit at most ∫ f. For the reverse, take a simple function φ with 0 ≤ φ ≤ f, and fix c with 0 < c < 1. Let Aₙ = {fₙ ≥ c φ}. These sets increase to the whole space, because fₙ increases to something at least φ. Then ∫ fₙ ≥ ∫_{Aₙ} c φ, and the right side increases to c ∫ φ by continuity of measure on the finite-measure pieces of a simple function. Let c approach 1, then take the supremum over all such φ. That supremum is ∫ f. So the limit of the integrals is at least ∫ f, and the two bounds match.",
  },
  "mp-fatou": {
    notation: "lim inf fₙ is the limit of the running infima, the largest height that is eventually a lower limit. The integrals of the fₙ may oscillate. lim inf of those integrals is the corresponding lower limit of numbers. The functions are nonnegative.",
    proof: "Let gₖ = inf_{n ≥ k} fₙ. Then 0 ≤ gₖ ≤ fₙ for every n ≥ k, and gₖ increases pointwise to lim inf fₙ. The monotone convergence theorem gives ∫ gₖ → ∫ lim inf fₙ. Also ∫ gₖ ≤ inf_{n ≥ k} ∫ fₙ, because gₖ sits under every later fₙ. Take the limit in k. The right side becomes lim inf ∫ fₙ. Therefore ∫ lim inf fₙ ≤ lim inf ∫ fₙ. Equality can fail. Indicators of [n, n+1] drift out to infinity, their integrals stay 1, and the lim inf of the functions is 0.",
  },
  "mp-dct": {
    notation: "|fₙ| ≤ g says g dominates every function in the sequence. g ∈ L¹ says g is integrable. fₙ → f is pointwise convergence. The conclusion is convergence of the integrals, not only an inequality.",
    proof: "The domination makes f integrable, since |f| ≤ g. Apply Fatou’s lemma to the nonnegative functions g + fₙ: ∫(g + f) ≤ lim inf ∫(g + fₙ) = ∫ g + lim inf ∫ fₙ, so ∫ f ≤ lim inf ∫ fₙ. Apply Fatou to g − fₙ: ∫(g − f) ≤ ∫ g − lim sup ∫ fₙ, so ∫ f ≥ lim sup ∫ fₙ. The lim inf and the lim sup of the integrals are therefore both equal to ∫ f, which is convergence. Without an integrable roof the conclusion fails. The drifting bumps fₙ = 1_{[n, n+1]} converge pointwise to 0 while every integral equals 1.",
  },
  "mp-rv": {
    notation: "μ_X is the law, or distribution, of the random variable X. B is a Borel set on the line. P(X ∈ B) is the probability of the event consisting of the outcomes ω where X(ω) lands in B.",
    proof: "Define μ_X(B) = P(X^{−1}(B)). Preimages preserve complements and countable disjoint unions, and P is a measure, so μ_X is a measure on the Borel sets. If X is real-valued, X^{−1}(ℝ) is the whole sample space and μ_X(ℝ) = 1. This measure is exactly the data of P(X ∈ B) for every Borel B, which is the displayed formula. Two random variables on different sample spaces can have the same law. The law determines every probability that depends only on the value of X, and it forgets every event that is not a condition on that value.",
  },
  "mp-expectation": {
    notation: "Var(X) is the variance. E is expectation, the integral against P. EX is the mean, a constant. (X − EX)² is the squared deviation. The outer E averages that square.",
    proof: "The displayed equation is the definition of variance for a square-integrable random variable. It is nonnegative because it is the expectation of a square. It equals the computational formula. Let μ = EX. Expand E[(X − μ)²] = E[X² − 2μX + μ²] = E[X²] − 2μ E[X] + μ² = E[X²] − μ², where the cross term uses linearity and E[X] = μ. So Var(X) = E[X²] − (EX)². The definition is what the shortcut is computing. If the second moment is infinite, both expressions are left undefined rather than given the value ∞ by force of habit.",
  },
  "mp-conditional": {
    notation: "E[X | G] is the conditional expectation of X given the sigma-algebra G. The integrals are against P. A ranges over events that belong to G, the information being conditioned on. Equality is required for every such A.",
    proof: "A conditional expectation is defined to be a G-measurable integrable random variable Y satisfying the displayed identity. Uniqueness: if Y and Y' both work, then ∫_A (Y − Y') = 0 for every A in G. The set where Y − Y' > 0 is in G, and an integrable function whose integral over every measurable set vanishes is zero almost surely. Existence: the set function ν(A) = ∫_A X dP is a signed measure on G, absolutely continuous with respect to P. The Radon–Nikodym theorem supplies a G-measurable density Y, and that density is E[X | G]. In L² the same Y is the orthogonal projection onto the G-measurable square-integrable random variables, because ∫ (X − Y) Z = 0 for every bounded G-measurable Z, by writing Z as a limit of simple functions built from sets in G.",
  },
  "mp-lln": {
    notation: "The fraction is the sample average of the first n variables. The arrow is almost-sure convergence: for almost every outcome, the sequence of averages converges. E[X₁] is the common mean. The Xᵢ are independent and identically distributed.",
    proof: "First suppose the variables are i.i.d. with mean μ and finite variance. Kolmogorov’s inequality says that if Sₖ are partial sums of independent mean-zero variables, then P(max_{k ≤ n} |Sₖ| ≥ ε) ≤ Var(Sₙ)/ε². Applied to Xₖ/k, the variances ∑ σ²/k² converge, so the partial sums of Xₖ/k are almost surely Cauchy and the series ∑ (Xₖ − μ)/k converges almost surely. Kronecker’s lemma turns a convergent series ∑ yₖ and weights bₖ = k into (1/n) ∑_{k=1}^{n} k yₖ → 0. Taking yₖ = (Xₖ − μ)/k gives (Sₙ − nμ)/n → 0 almost surely. If only the mean exists, truncate: let Yₙ = Xₙ 1_{|Xₙ| ≤ n}. Finite mean implies ∑ P(|X₁| > n) < ∞, so Borel–Cantelli gives Xₙ = Yₙ for all large n, almost surely, and the averages of X and of Y share the same limit. The truncated variables satisfy the variance test ∑ Var(Yₙ)/n² < ∞, and their means approach μ. The same series argument returns the average to μ.",
  },
  "mp-clt": {
    notation: "Sₙ is the sum of the first n variables. nμ centers it. σ √n scales it. The double arrow means convergence in distribution. N(0, 1) is the standard normal law. The variables are i.i.d. with mean μ and variance σ² > 0.",
    proof: "Let Zₙ = (Sₙ − nμ)/(σ √n), and let Yᵢ = (Xᵢ − μ)/σ, so the Yᵢ have mean 0 and variance 1, and Zₙ = (Y₁ + ··· + Yₙ)/√n. The characteristic function of Y₁ has the expansion φ(u) = 1 − u²/2 + o(u²) as u → 0, because the first two moments exist. The characteristic function of Zₙ is [φ(t/√n)]ⁿ = [1 − t²/(2n) + o(1/n)]ⁿ, which tends to e^{−t²/2}. That is the characteristic function of N(0, 1). Lévy’s continuity theorem says that pointwise convergence of characteristic functions to a characteristic function which is continuous at 0 implies convergence in distribution. Therefore Zₙ converges in distribution to N(0, 1). The convergence is not almost sure: the standardized sum keeps moving forever.",
  },
  "mp-radon-nikodym": {
    notation: "ν and μ are measures, with ν absolutely continuous with respect to μ: every μ-null set is ν-null. dν/dμ is the density, a nonnegative measurable function. The integral rebuilds ν(A) by weighting μ with that density.",
    proof: "The inclusion √ of the easy direction is immediate, but here the claim is existence of the density. Assume first that μ and ν are finite. Among nonnegative measurable functions f with ∫_A f dμ ≤ ν(A) for every A, choose a sequence whose integrals approach the supremum of possible integrals, and let f be the pointwise supremum. Then ∫ f dμ is that supremum. The set function ν − f μ is a positive measure. If it charged a set of positive μ measure, the Hahn decomposition of a suitable difference would produce a subset on which one could add a small multiple of the indicator and increase the integral, contradicting the supremum. So ν − f μ vanishes, and f = dν/dμ. If two densities work, their difference integrates to 0 over every set and is 0 almost everywhere. A sigma-finite measure splits into countably many finite pieces, and the densities on the pieces glue together.",
  },
  "mp-borel-cantelli": {
    notation: "P(Aₙ) is the probability of the n-th event. The sum being finite is the hypothesis. “i.o.” means infinitely often: the outcomes that lie in infinitely many of the events. The conclusion is that this set has probability 0. Independence is not assumed.",
    proof: "The event that infinitely many Aₙ occur is ⋂_N ⋃_{n ≥ N} Aₙ. For each N, P(⋃_{n ≥ N} Aₙ) ≤ ∑_{n ≥ N} P(Aₙ) by countable subadditivity. The tail of a convergent series tends to 0, so those probabilities tend to 0. The intersection is contained in every one of the unions, so its probability is at most every tail and equals 0. The matching divergence statement is false without independence. Repeating one event of probability 1/2 gives probabilities that sum to infinity, while the probability of occurring infinitely often equals 1/2.",
  },
  "fr-series": {
    notation: "cₙ is the n-th Fourier coefficient, n any integer. The integral runs over one full period, from −π to π. e^{−inx} is the conjugate character. The factor 1/(2π) normalizes the integral of |e^{inx}|², which equals 2π.",
    proof: "The characters satisfy ∫_{−π}^{π} e^{i(k−n)x} dx = 2π if k = n and 0 otherwise, by direct integration. Suppose f = ∑_k cₖ e^{ikx} with the series converging uniformly. Multiply by e^{−inx}, integrate, and pass the sum through the integral. Every term vanishes except k = n, which contributes 2π cₙ. Divide by 2π to recover cₙ. For a general integrable f the same integral is used as the definition of cₙ. The calculation shows that the definition is forced by orthogonality whenever the series represents f.",
  },
  "fr-coefficients": {
    notation: "⟨ , ⟩ is an inner product. φₙ is one vector of an orthogonal family, not the zero vector. cₙ is the coefficient of φₙ in the expansion of f. The denominator is the squared length of φₙ.",
    proof: "Suppose f = ∑_k cₖ φₖ, with the sum converging in the inner-product space, and suppose ⟨φₖ, φₙ⟩ = 0 for k ≠ n. Take the inner product of both sides with φₙ. The cross terms vanish, leaving ⟨f, φₙ⟩ = cₙ ⟨φₙ, φₙ⟩. The denominator is nonzero because φₙ is not zero. Divide to obtain the formula. On the trigonometric system the denominator ⟨e^{inx}, e^{inx}⟩ over [−π, π] equals 2π, and the formula reduces to the integral for cₙ.",
  },
  "fr-parseval": {
    notation: "The left side is the average of |f|² over one period. cₙ are the Fourier coefficients with the 1/(2π) normalization. The sum of |cₙ|² runs over every integer. Equality is an identity of energies.",
    proof: "If f is a trigonometric polynomial ∑ cₙ e^{inx}, expand ∫ |f|² = ∫ f \overline{f}. Orthogonality kills every cross term, and each diagonal term contributes 2π |cₙ|². Divide by 2π. For a general f in L², the partial sums sₙ are the orthogonal projections of f onto the span of the characters up to frequency n. They converge to f in L², and ∥f − sₙ∥² = ∥f∥² − ∥sₙ∥² by Pythagoras in the inner product. The tail of ∑ |cₙ|² is a constant times that remainder and tends to 0. Passing to the limit gives the identity for f.",
  },
  "fr-transform": {
    notation: "hat f(ξ) is the Fourier transform at frequency ξ. The integral runs over the whole line. e^{−iξx} is the complex oscillation of frequency ξ. No constant sits in front: in this convention the 2π appears in the inversion, not here.",
    proof: "The displayed integral is the definition of the Fourier transform used on this card, for an integrable f. It is forced by the inversion formula. If f and hat f are both integrable, then f(x) = (1/(2π)) ∫ hat f(ξ) e^{iξx} dξ at points of continuity. The sign in the exponent flips between the two integrals, and exactly one of them carries 1/(2π). To see the constant, apply both maps to a Gaussian. The transform of e^{−x²/2} is √(2π) e^{−ξ²/2} in this convention, and feeding that through the inversion reproduces the Gaussian only when the factor is 1/(2π). Changing the convention moves that factor, but then this displayed line changes with it.",
  },
  "fr-convolution": {
    notation: "f ∗ g is the convolution (f ∗ g)(x) = ∫ f(y) g(x − y) dy. The hat on the left is the transform of that convolution. The right side is the ordinary product of the two transforms, in the convention with no constant in front of the forward integral.",
    proof: "Compute hat{f ∗ g}(ξ) = ∫ (∫ f(y) g(x − y) dy) e^{−iξx} dx. For f and g integrable the double integral is absolutely convergent, so Fubini applies. Substitute x = y + u. Then e^{−iξx} = e^{−iξy} e^{−iξu}, and the integral splits into (∫ f(y) e^{−iξy} dy)(∫ g(u) e^{−iξu} du). That is hat f(ξ) hat g(ξ). The identity is an equality of functions of ξ. The reverse direction, a product of functions becoming a convolution of transforms, picks up the factor 1/(2π) in this convention. It is a different formula.",
  },
  "fr-plancherel": {
    notation: "∥ ∥₂ is the L² norm, the square root of the integral of the square. hat f is the Fourier transform in the unitary convention, with a factor 1/√(2π) on the forward integral and the same factor on the inverse. The equality says this transform preserves the norm.",
    proof: "In the asymmetric convention, ∫ |hat f|² = 2π ∫ |f|² for Schwartz f. This is Parseval’s identity, proved by writing the integral of hat f against a Gaussian approximation of the identity and passing to the limit, or by checking it on Gaussians and using that they span a dense set. The unitary transform divides the asymmetric transform by √(2π). The factor 2π under the square root becomes √(2π), which cancels that division. So the unitary transform preserves the L² norm on Schwartz functions. Schwartz functions are dense in L², and a linear isometry on a dense subspace extends uniquely to a linear isometry of the whole space. That extension is the Fourier transform of a general L² function. The equality does not hold for the asymmetric convention, which multiplies the norm by √(2π).",
  },
  "fr-uncertainty": {
    notation: "σₓ is the standard deviation of |f|² in the x variable, the root-mean-square distance from the mean. σ_ξ is the same spread for the unitary Fourier transform. The function is normalized by ∫ |f|² = 1. The bound is the number 1/2.",
    proof: "Translate f so that the mean of x is 0, and modulate it so that the mean of ξ is 0. These moves do not change the product of the spreads. In the unitary convention, differentiation corresponds to multiplication by iξ and preserves the L² norm, so σ_ξ = ∥f'∥₂ and σₓ = ∥x f∥₂. Integrate by parts, using that a Schwartz function vanishes at infinity: ∫ |f|² = −∫ x (f \overline{f})' dx = −∫ x (f' \overline{f} + f \overline{f'}) dx. The right side has absolute value at most 2 ∫ |x f| |f'| dx. Cauchy–Schwarz bounds that by 2 ∥x f∥₂ ∥f'∥₂. Since ∫ |f|² = 1, one gets 1 ≤ 2 σₓ σ_ξ. Equality holds when x f and f' are linearly dependent and the integration by parts is sharp, which is the Gaussian.",
  },
  "fr-heat": {
    notation: "hat u(ξ, t) is the Fourier transform in x, with t kept as a parameter. hat u(ξ, 0) is the transform of the initial temperature. k is the diffusion constant. e^{−k ξ² t} is the multiplier that damps frequency ξ.",
    proof: "Start from the heat equation u_t = k u_{xx}, with u(x, 0) given and u decaying so that the transform in x is legitimate. Transform both sides in x. Differentiation in t passes outside the integral, and two derivatives in x multiply by (iξ)² = −ξ². The result is the ordinary differential equation ∂_t hat u(ξ, t) = −k ξ² hat u(ξ, t). Its solution is hat u(ξ, 0) times e^{−k ξ² t}. High frequencies, large |ξ|, are multiplied by a much smaller factor than low frequencies. That is the cooling of sharp edges.",
  },
  "fr-dirac": {
    notation: "δ is the Dirac delta. φ is a test function, smooth and compactly supported. The angle brackets mean the action of a distribution on a test function. φ(0) is the value of the test function at the origin.",
    proof: "The equation is the definition of δ as a distribution: it sends each test function to its value at 0. It is the limit of ordinary functions. If ρ is a nonnegative bump with integral 1 and ρ_ε(x) = ρ(x/ε)/ε, then ∫ ρ_ε(x) φ(x) dx → φ(0) as ε → 0, because φ is continuous at 0 and the bumps concentrate there. So the formula is the limiting action of an approximation of the identity. Delta is not given by integration against a locally integrable function. Such a function would have to vanish almost everywhere off {0}, and integration against it would give 0, while φ(0) need not be 0.",
  },
  "fa-norm": {
    notation: "|u + v| is the length of a sum of vectors. |u| and |v| are the separate lengths. The inequality says the length of a sum never exceeds the sum of the lengths.",
    proof: "A norm is required to satisfy this inequality; it is one of the axioms, together with positive-definiteness and absolute homogeneity. For a norm that comes from an inner product it is a theorem. Expand |u + v|² = |u|² + |v|² + 2 Re ⟨u, v⟩. Cauchy–Schwarz gives Re ⟨u, v⟩ ≤ |⟨u, v⟩| ≤ |u| |v|. Therefore |u + v|² ≤ |u|² + |v|² + 2|u||v| = (|u| + |v|)². Lengths are nonnegative, so take square roots. The metric d(u, v) = |u − v| inherits the triangle inequality from this line, because |u − w| = |(u − v) + (v − w)| ≤ |u − v| + |v − w|.",
  },
  "fa-hilbert": {
    notation: "|v|² is the squared length in a Hilbert space. eₙ runs over a Hilbert basis, a complete orthonormal set. ⟨v, eₙ⟩ is the n-th coefficient. The sum of the squared moduli of the coefficients rebuilds the squared length.",
    proof: "Let sₙ = ∑_{k=1}^{n} ⟨v, eₖ⟩ eₖ. Orthonormality gives |sₙ|² = ∑_{k=1}^{n} |⟨v, eₖ⟩|². The remainder v − sₙ is orthogonal to each e₁, …, eₙ, because ⟨v − sₙ, eⱼ⟩ = ⟨v, eⱼ⟩ − ⟨v, eⱼ⟩ = 0. Pythagoras in the inner product says |v|² = |v − sₙ|² + |sₙ|². A Hilbert basis has dense span, and sₙ is the nearest point of that span, so |v − sₙ| → 0. Therefore |v|² equals the sum of every |⟨v, eₙ⟩|². Dropping the squares, or summing the coefficients themselves, is a different and generally false statement.",
  },
  "fa-bounded-op": {
    notation: "∥T∥ is the operator norm of a linear map T. The supremum runs over all vectors of length at most 1. |Tv| is the length of the output. The sup is the smallest number that bounds those outputs.",
    proof: "The displayed formula is the definition of the operator norm. It is finite exactly when T is bounded. It controls every vector: if v ≠ 0, then v/|v| has length 1, so |T(v/|v|)| ≤ ∥T∥, which multiplies out to |Tv| ≤ ∥T∥ |v|. The constant is sharp. If a smaller number c worked for every vector, it would bound |Tv| on the unit ball and contradict the definition of the supremum. The same number equals sup_{|v|=1} |Tv| and sup_{v ≠ 0} |Tv|/|v|, because scaling does not change the ratio.",
  },
  "fa-riesz": {
    notation: "φ is a continuous linear functional on a Hilbert space. ⟨v, u⟩ is the inner product with a fixed vector u. ∥φ∥ is the operator norm of φ. |u| is the length of the representing vector. Both claims are part of the line.",
    proof: "Given u, the functional φ(v) = ⟨v, u⟩ is linear, and Cauchy–Schwarz gives |φ(v)| ≤ |u| |v|, so ∥φ∥ ≤ |u|. If u ≠ 0, the unit vector u/|u| produces |φ(u/|u|)| = |u|, so ∥φ∥ ≥ |u|. The two inequalities give ∥φ∥ = |u|, which is the second claim, once the first claim’s representation exists. For existence, if φ = 0 take u = 0. Otherwise ker φ is a closed hyperplane. Choose a unit vector n orthogonal to it, which exists because the orthogonal complement of a proper closed subspace is nontrivial. Set u = \overline{φ(n)} n in the complex case, or u = φ(n) n in the real case. For arbitrary v, the vector v − (φ(v)/φ(n)) n lies in the kernel, hence is orthogonal to n. Taking the inner product with u recovers φ(v).",
  },
  "fa-spectrum": {
    notation: "σ(T) is the spectrum of a bounded operator T on a Banach space X. λ is a scalar. T − λI is the operator shifted by λ. B(X) is the algebra of bounded operators on X, and invertible means invertible inside that algebra: a bounded inverse defined on all of X.",
    proof: "The displayed set is the definition of the spectrum. For a square matrix it coincides with the set of eigenvalues. T − λI fails to be invertible if and only if its determinant is 0, if and only if its kernel is nontrivial, if and only if Av = λv for some v ≠ 0. In infinite dimensions the three failures come apart. An operator can be injective and still fail to be surjective, or the inverse can exist on the range and fail to be bounded. Any of those puts λ in the spectrum without making λ an eigenvalue. The definition uses all three failures at once by asking for invertibility in B(X).",
  },
  "fa-projection": {
    notation: "H is a Hilbert space. M is a closed subspace. M⊥ is the set of vectors orthogonal to every vector in M. ⊕ says every vector of H splits uniquely as a sum of one vector from each summand.",
    proof: "Fix v in H. The distance from v to M is the infimum of |v − m| over m in M. A minimizing sequence is Cauchy by the parallelogram law: the midpoints stay in M because M is a subspace, and convexity of the closed ball forces the terms together. Completeness of H and closedness of M produce a limit p in M with |v − p| minimal. For any m in M and any scalar t, |v − p|² ≤ |v − p − t m|². Expand and let t approach 0. The cross term must vanish, or a small t of the right sign would decrease the distance. So ⟨v − p, m⟩ = 0 for every m, which says v − p lies in M⊥. Thus v = p + (v − p). If v = m₁ + n₁ = m₂ + n₂, then m₁ − m₂ = n₂ − n₁ lies in M ∩ M⊥ = {0}. The sum is direct.",
  },
  "pd-classification": {
    notation: "a, b, and h are the coefficients of u_{xx}, u_{yy}, and the mixed term in a second-order equation, written so the mixed coefficient is 2h. h² − ab is the discriminant. The three cases name the type.",
    proof: "The principal part a u_{xx} + 2h u_{xy} + b u_{yy} has symbol a ξ² + 2h ξη + b η². As a quadratic form in (ξ, η), its discriminant is 4(h² − ab). If h² − ab > 0 the form factors into two distinct real linear factors, so there are two real characteristic directions. Coordinates straightened along those directions reduce the principal part to a multiple of u_{ξη}, the wave operator in characteristic coordinates. If h² − ab = 0 there is one real characteristic family, and the principal part reduces to a multiple of a pure second derivative in one variable, the heat operator after the remaining first-order term is used to name time. If h² − ab < 0 there is no real characteristic direction, the quadratic form is definite, and a linear change reduces it to the Laplacian. The sign of h² − ab is unchanged by smooth coordinate changes that keep the equation nondegenerate, so the type is well-defined.",
  },
  "pd-laplace": {
    notation: "Δ is the Laplacian, the sum of the pure second partial derivatives. u is a twice differentiable function of several variables. The equation says that sum is identically zero.",
    proof: "The equation is the definition of a harmonic function, and it is equivalent to the mean-value property. Let A(r) be the average of u over the sphere of radius r about a point. Differentiating under the integral and using the divergence theorem, A'(r) equals a constant times the average of ∂u/∂n, which equals a constant times the integral of Δu over the ball, divided by the surface area. If Δu = 0, then A'(r) = 0, so A(r) is constant. Let r → 0. The spherical average approaches u at the center. So a harmonic function equals its average over every sphere. Conversely, if the averages are constant, the same identity forces the integral of Δu over every ball to vanish, and continuity of Δu forces Δu = 0.",
  },
  "pd-heat": {
    notation: "u_t is the partial derivative of temperature with respect to time. k is a positive constant, the diffusivity. Δu is the Laplacian in the space variables. The equation balances the rate of change against the curvature in space.",
    proof: "Fourier’s law says heat flows in the direction opposite the gradient, with flux −k ∇u. Conservation says the temperature at a point rises exactly when heat flows in, so u_t + div(flux) = 0 in the absence of sources. The divergence of −k ∇u is −k Δu when k is constant. Therefore u_t = k Δu. The sign is fixed by the physics: a function that bends downward, with Δu < 0 at a maximum, must decrease there. The same equation with a minus on the right would blow maxima up, and it is not the heat equation.",
  },
  "pd-wave": {
    notation: "u(x, t) is the displacement. f is the initial displacement and g the initial velocity. c is the wave speed. The fraction averages the initial displacement from the two points x − ct and x + ct. The integral of g runs between those same two points and is scaled by 1/(2c).",
    proof: "For u_{tt} = c² u_{xx} on the line, change variables to ξ = x − ct and η = x + ct. The chain rule turns the equation into u_{ξη} = 0. Integrate: u = F(ξ) + G(η) = F(x − ct) + G(x + ct). The initial displacement says F(x) + G(x) = f(x). Differentiate in t and set t = 0: −c F'(x) + c G'(x) = g(x). Solve the linear system: F' = (f' − g/c)/2 and G' = (f' + g/c)/2. Integrate and add. The constants cancel, and ∫_0^{x+ct} g − ∫_0^{x−ct} g = ∫_{x−ct}^{x+ct} g. Therefore u(x, t) = (f(x − ct) + f(x + ct))/2 + (1/(2c)) ∫_{x−ct}^{x+ct} g. Differentiating under the assumptions that f is twice differentiable and g once differentiable recovers the wave equation and the two initial conditions.",
  },
  "pd-characteristics": {
    notation: "u_t and u_x are partial derivatives. b is a constant speed. u₀ is the profile at time 0. x − bt is the foot of the characteristic through (x, t).",
    proof: "Along the line x(t) = x₀ + bt, the chain rule gives d/dt u(x(t), t) = b u_x + u_t. The differential equation says this derivative is 0, so u is constant on each such line. The line through the point (x, t) meets the initial line t = 0 at the point x − bt. Therefore u(x, t) equals the initial value u₀(x − bt). Conversely, a profile carried rigidly at speed b has u_t = −b u₀'(x − bt) and b u_x = b u₀'(x − bt), so the equation holds wherever u₀ is differentiable.",
  },
  "pd-weak": {
    notation: "u' and φ' are derivatives in one variable. φ is a test function, smooth and vanishing at the ends of the interval. f is the given right-hand side. The integrals are over the interval. No second derivative of u is written.",
    proof: "Suppose −u'' = f, with u twice differentiable, and suppose φ vanishes at the endpoints. Multiply by φ and integrate: −∫ u'' φ = ∫ f φ. Integrate the left side by parts. The boundary term [−u' φ] vanishes because φ does. One integration moves a derivative onto φ and removes the minus: ∫ u' φ' = ∫ f φ. This identity still makes sense when u is merely absolutely continuous with u' square-integrable and f is integrable. It is the definition of a weak solution of −u'' = f. The sign is the one obtained from −u'' = f. The equation u'' = f would flip it.",
  },
  "de-picard": {
    notation: "y(t) is the unknown solution. y₀ is the prescribed value at time t₀. f(s, y(s)) is the slope given by the differential equation at time s. The integral adds those slopes from t₀ to t.",
    proof: "If y is differentiable, y' = f(t, y), and y(t₀) = y₀, the fundamental theorem of calculus says y(t) − y(t₀) = ∫_{t₀}^{t} y'(s) ds. Substitute the two pieces of data to get the integral equation. Conversely, if y is continuous and satisfies the integral equation, the integrand s ↦ f(s, y(s)) is continuous when f is continuous, so the right side is differentiable. Differentiating by the fundamental theorem gives y'(t) = f(t, y(t)). Setting t = t₀ makes the integral vanish, so y(t₀) = y₀. The two problems have the same solutions. Picard iteration is the contraction mapping applied to the integral operator, which is why this form of the equation is the one used to prove existence.",
  },
  "de-linear-first": {
    notation: "μ is the integrating factor. ∫ p is an antiderivative of the coefficient p(t) in y' + p y = g. The second equation says the derivative of μ y equals μ times the right-hand side g.",
    proof: "Let μ = exp(∫ p dt). Then μ' = p μ, and μ is never zero. Compute (μ y)' = μ' y + μ y' = μ (y' + p y). If y solves y' + p y = g, the parenthesis is g, so (μ y)' = μ g. Conversely, if (μ y)' = μ g, divide by μ to recover y' + p y = g. To solve the equation, integrate μ g and divide by μ. The factor is built so that the left side becomes an exact derivative. Any other nonzero multiple of μ does the same job.",
  },
  "de-wronskian": {
    notation: "W(y₁, y₂) is the Wronskian of two differentiable functions. y₁' and y₂' are their derivatives. The expression is the determinant of the matrix whose rows are (y₁, y₂) and (y₁', y₂').",
    proof: "The determinant y₁ y₂' − y₂ y₁' is zero at a point exactly when the two vectors (yᵢ(t), yᵢ'(t)) are linearly dependent there. Suppose y₁ and y₂ both solve the same second-order linear equation y'' + p y' + q y = 0. If the Wronskian vanishes at t₀, there are constants, not both zero, with c₁ y₁ + c₂ y₂ = 0 and c₁ y₁' + c₂ y₂' = 0 at t₀. The function c₁ y₁ + c₂ y₂ then solves the equation with zero initial data at t₀. Uniqueness of the initial-value problem forces it to be identically zero. So the solutions are linearly dependent on the whole interval. Conversely, a linear dependence makes the two rows of the Wronskian matrix proportional everywhere, so the determinant vanishes. The displayed formula is the determinant whose vanishing detects that dependence.",
  },
  "de-variation": {
    notation: "y₁ and y₂ are two independent solutions of the homogeneous equation. u₁ and u₂ are unknown functions of t. The primes are derivatives. g is the forcing term in the nonhomogeneous equation. The two equations are a linear system for u₁' and u₂'.",
    proof: "Look for a solution of y'' + p y' + q y = g in the form y = u₁ y₁ + u₂ y₂. Differentiate: y' = u₁' y₁ + u₁ y₁' + u₂' y₂ + u₂ y₂'. Impose the first displayed equation, u₁' y₁ + u₂' y₂ = 0. The formula for y' simplifies to u₁ y₁' + u₂ y₂', with no derivatives of the u’s left. Differentiate again: y'' = u₁' y₁' + u₁ y₁'' + u₂' y₂' + u₂ y₂''. Substitute into the differential equation. Every term that contains u₁ or u₂, rather than u₁' or u₂', cancels, because y₁ and y₂ solve the homogeneous equation. What remains is u₁' y₁' + u₂' y₂' = g. Together with the imposed equation, that is the displayed system. Its coefficient determinant is the Wronskian, nonzero because y₁ and y₂ are independent.",
  },
  "de-lyapunov": {
    notation: "V is a scalar function of the state. The dot is the derivative of V along a trajectory. ∇V is its gradient. f is the vector field of the system x' = f(x). The inequality says this directional derivative is never positive.",
    proof: "If x(t) solves x' = f(x), the chain rule gives d/dt V(x(t)) = ∇V(x(t)) · x'(t) = ∇V · f. That is the identity in the formula. The inequality ∇V · f ≤ 0 is the hypothesis that V does not increase along trajectories. Under it, t ↦ V(x(t)) is nonincreasing. If in addition V is positive away from an equilibrium and zero there, a trajectory that starts close to the equilibrium stays close: leaving a neighborhood would require V to climb, and V cannot climb. The identity is the chain rule. The inequality is the condition one has to check on V and f.",
  },
  "de-laplace": {
    notation: "L is the Laplace transform, ∫_0^{∞} (·) e^{−st} dt. y' is the derivative. Y is the transform of y. s is the transform variable. y(0) is the initial value, a number, subtracted after multiplication by s.",
    proof: "Compute ∫_0^{∞} y'(t) e^{−st} dt by parts. Let u = e^{−st} and dv = y' dt, so du = −s e^{−st} dt and v = y. The boundary term is [y(t) e^{−st}]_0^{∞}. For y of exponential order and s large enough, the term at infinity vanishes, and the term at 0 is −y(0). The remaining integral is s ∫_0^{∞} y(t) e^{−st} dt = s Y. Therefore L{y'} = s Y − y(0). Each extra derivative brings another factor of s and subtracts the corresponding initial value. The formula is how initial conditions enter an algebraic equation for Y.",
  },
  "de-sturm": {
    notation: "p, q, and w are given functions of the independent variable, with p and w positive. y is the unknown function. λ is the eigenvalue. The left side is a second-order operator written as a derivative of p y' plus q y. The right side weights y by w.",
    proof: "Start from a general equation a(x) y'' + b(x) y' + c(x) y = λ y, with a > 0. Multiply through by (1/a) exp(∫ b/a dx). The left side becomes an exact derivative: it equals (p y')' + (a rewritten lower term) y, where p = exp(∫ b/a). Move the zero-order term to the form q y and divide the weight into w. The result is the displayed self-adjoint form. Self-adjointness is the identity ∫ (v L u − u L v) dx = [p (u v' − v u')] at the ends, where L y = −(p y')' + q y. It follows by integrating (v (p u')' − u (p v')') by parts; the interior terms cancel. For two eigenfunctions with different eigenvalues, the boundary term vanishes under separated boundary conditions, so ∫ y₁ y₂ w dx = 0. The weight w is what the orthogonality is measured against.",
  },
  "ds-iteration": {
    notation: "xₙ is the state at step n. f is a fixed function. x_{n+1} is the next state. The equation says the next state is f applied to the current one.",
    proof: "The equation is the definition of iterating f. By induction, xₙ = f composed with itself n times, applied to x₀. The base case n = 0 is the starting value. If xₙ = f^{∘n}(x₀), the recurrence gives x_{n+1} = f(xₙ) = f^{∘(n+1)}(x₀). Changing the starting value changes the orbit. Changing f changes the rule. The orbit is the list x₀, f(x₀), f(f(x₀)), and so on, and nothing else.",
  },
  "ds-fixed": {
    notation: "x* is a fixed point, so f(x*) = x*. f'(x*) is the derivative there. The absolute value less than 1 says the slope is strictly between −1 and 1. “Attracting” means nearby orbits converge to x*.",
    proof: "Since f is differentiable at x*, f(x) = x* + f'(x*)(x − x*) + ε(x)(x − x*), where ε(x) → 0 as x → x*. Choose a neighborhood on which |f'(x*)| + |ε(x)| ≤ k for some k with |f'(x*)| < k < 1. Inside that neighborhood, |f(x) − x*| ≤ k |x − x*|. The image of the neighborhood stays inside, and iterating gives |f^{∘n}(x) − x*| ≤ kⁿ |x − x*|. Because k < 1, the right side tends to 0. So every start sufficiently close to x* has orbit converging to x*. If |f'(x*)| > 1 the same expansion pushes nearby points away, and the fixed point is repelling.",
  },
  "ds-periodic": {
    notation: "f^{∘n} is f composed with itself n times. The prime is the derivative of that composition, evaluated at x. The product runs from k = 0 to n − 1. f^{∘k}(x) is the point k steps along the orbit. f' there is the slope at that point.",
    proof: "Proceed by induction on n. For n = 1 the product has the single factor f'(x), and the derivative of f is f'. Assume the formula for n − 1. The chain rule applied to f ∘ f^{∘(n−1)} gives (f^{∘n})'(x) = f'(f^{∘(n−1)}(x)) · (f^{∘(n−1)})'(x). The induction hypothesis replaces the second factor by the product up through k = n − 2. The new factor is the missing term k = n − 1. For a periodic point of period n, this product is the multiplier of the cycle. Its absolute value, not the derivative of f at any single point of the cycle, decides whether the cycle attracts.",
  },
  "ds-logistic": {
    notation: "f_r is the logistic map with parameter r. x is the state, read as a fraction of a maximum population. r x is proportional growth. (1 − x) shrinks the growth as x approaches the ceiling 1.",
    proof: "A discrete population model takes the next population proportional to the current one, x ↦ r x, and then reduces the rate in proportion to the population already present, replacing r by r(1 − x) when the ceiling has been scaled to 1. The composition is f_r(x) = r x (1 − x). Expanding gives the quadratic r x − r x². The fixed points solve x = r x (1 − x). One solution is x = 0. For r ≠ 0 the other is x = 1 − 1/r, which lies in (0, 1) when r > 1. The derivative is f_r'(x) = r − 2 r x, so at the nonzero fixed point the multiplier is r − 2 r (1 − 1/r) = 2 − r. It has absolute value less than 1 precisely when 1 < r < 3, which is the range where that fixed point attracts.",
  },
  "ds-conservative": {
    notation: "Df is the Jacobian matrix of partial derivatives of the map f. det is its determinant. The absolute value equals 1. In the plane, this is the condition that f preserves area.",
    proof: "A small parallelogram based at a point, spanned by vectors v and w, is sent to a parallelogram spanned approximately by Df(v) and Df(w). The signed area of a parallelogram is the determinant of the matrix with those columns, so the image area equals det(Df) times the original area. The absolute value of the determinant is therefore the factor by which area is multiplied. It equals 1 exactly when every infinitesimal area is preserved, orientation allowed to reverse when the determinant is −1. For a flow of a vector field, Liouville’s theorem says the Jacobian determinant along the flow stays 1 for all time precisely when the divergence of the field is 0. The displayed test is the map version of that conservation.",
  },
  "nm-float": {
    notation: "fl is the floating-point rounding map. ⊕ is the floating-point addition, the addition the machine actually performs. δ is the relative rounding error. ε_mach is machine epsilon, the unit roundoff.",
    proof: "A floating-point number system rounds a real in the normalized range to a nearby representable number. For round-to-nearest, the relative error satisfies fl(z) = z (1 + δ) with |δ| ≤ ε_mach, as long as z does not overflow or underflow. Floating-point addition is defined to return the rounding of the exact sum, when the exact sum is in range: x ⊕ y = fl(x + y). Combine the two statements: x ⊕ y = (x + y)(1 + δ) with |δ| ≤ ε_mach. The identity is a model of one operation. A string of operations accumulates one such factor per operation, and the model says nothing about overflow, where the computed result is no longer a relative perturbation of the true one.",
  },
  "nm-conditioning": {
    notation: "κ(A) is the condition number of an invertible matrix A. ∥A∥ is a matrix operator norm. ∥A^{−1}∥ is the operator norm of the inverse. The product is independent of scaling A by a nonzero constant.",
    proof: "Suppose A x = b and A(x + δx) = b + δb, with A held fixed. Then δx = A^{−1} δb, so |δx| ≤ ∥A^{−1}∥ |δb|. Also |b| = |A x| ≤ ∥A∥ |x|, so 1/|x| ≤ ∥A∥ / |b| when b ≠ 0. Multiply: |δx|/|x| ≤ ∥A∥ ∥A^{−1}∥ |δb|/|b|. The product in front is the displayed κ(A). It is the least constant that works for every right-hand side, because the operator norm is the least constant in each factor and there are vectors that nearly attain both. A relative error in b of size η can therefore appear in x amplified by κ(A). The formula is the definition, and this inequality is why that definition measures conditioning.",
  },
  "nm-stability": {
    notation: "Forward error is the relative distance between the computed answer and the true answer. Backward error is the relative size of the perturbation of the input that would make the computed answer exact. κ is the condition number. The approximation records the leading relationship.",
    proof: "A backward-stable algorithm returns the exact solution of a nearby problem. Let the perturbed input differ relatively by the backward error η. The conditioning inequality says the relative change in the true solution, between the original problem and the nearby one, is at most κ η, and is on the order of κ η for some perturbations that attain the operator norms. The computed answer is exact for the nearby problem, so its distance to the true answer of the original problem is that change in the solution. Therefore the forward error is about κ times the backward error. An algorithm can have a tiny backward error and still produce a large forward error when κ is large. The instability then belongs to the problem.",
  },
  "nm-newton-root": {
    notation: "xₙ is the current guess. f(xₙ) is the function value and f'(xₙ) the slope there. The fraction is how far to walk to reach the root of the tangent line. x_{n+1} is the next guess.",
    proof: "The tangent line at xₙ is y = f(xₙ) + f'(xₙ)(x − xₙ). Set y = 0 and solve, assuming f'(xₙ) ≠ 0: x = xₙ − f(xₙ)/f'(xₙ). That is the displayed update. If f(r) = 0, f'(r) ≠ 0, and f'' is continuous, the error shrinks quadratically. Taylor’s theorem gives f(xₙ) = f'(r) eₙ + f''(ξ) eₙ²/2 with eₙ = xₙ − r, and f'(xₙ) = f'(r) + O(eₙ). Divide: f(xₙ)/f'(xₙ) = eₙ + O(eₙ²). Subtract from xₙ: the next error is O(eₙ²). Once the guess is close enough that the O hides a constant times eₙ² with the constant times |eₙ| less than 1, the errors square at every step.",
  },
  "nm-elimination": {
    notation: "A is a square matrix. P is a permutation matrix, recording row swaps. L is unit lower triangular: ones on the diagonal and multipliers below. U is upper triangular. The product PA equals LU.",
    proof: "Gaussian elimination clears the first column below the pivot by subtracting multiples of the first row from the rows beneath. Those multipliers are the entries that belong in the first column of L. If a pivot is zero, or small, a row swap brings a nonzero pivot into place, and that swap is recorded by multiplying by a permutation. After the first column is cleared, the same process runs on the trailing submatrix. When every leading principal minor of the permuted matrix is nonzero, which partial pivoting arranges for a nonsingular matrix, each pivot is nonzero and the process finishes. Assembling the multipliers into L and the final triangular array into U gives PA = LU. Multiplying L by U reproduces the elimination because each column of multipliers undoes one stage of the clearing.",
  },
  "nm-finite-difference": {
    notation: "f'(x) is the derivative. h is the step. f(x+h) and f(x−h) are the values one step to either side. The fraction is the slope of the chord between those two points. O(h²) says the error is bounded by a constant times h² for small h.",
    proof: "Taylor expansion with a remainder gives f(x+h) = f(x) + f'(x) h + f''(x) h²/2 + f'''(ξ₊) h³/6, and f(x−h) = f(x) − f'(x) h + f''(x) h²/2 − f'''(ξ₋) h³/6. Subtract. The function values and the second-derivative terms cancel, leaving f(x+h) − f(x−h) = 2 f'(x) h + O(h³), provided f''' is bounded near x. Divide by 2h. The result is f'(x) + O(h²). The first-derivative errors cancel because the two steps have opposite signs, which is why the error starts at h² rather than at h. The one-sided quotient (f(x+h) − f(x))/h leaves an O(h) term from the second derivative.",
  },
  "tp-continuity": {
    notation: "V is an open set in the codomain Y. f^{−1}(V) is the set of points of X that f sends into V. The arrow says that this preimage is open in X. The implication is required for every open V.",
    proof: "The sentence is the definition of a continuous map between topological spaces. In metric spaces it matches the epsilon-delta definition. Suppose the preimage condition holds, and fix x and ε > 0. The ball B(f(x), ε) is open, so its preimage is open and contains x. Some ball B(x, δ) sits inside that preimage, which means d(x, y) < δ implies d(f(x), f(y)) < ε. Conversely, if f is epsilon-delta continuous and V is open, then for each x with f(x) in V some ball B(f(x), ε) sits in V, and the corresponding δ-ball around x is carried into that ball, hence into V. So the preimage contains a ball about each of its points and is open.",
  },
  "tp-metric": {
    notation: "d is a metric. x, y, and z are points. d(x, z) is the direct distance. The right side goes from x to z by way of y. The inequality says the direct distance is never longer.",
    proof: "The inequality is one of the axioms of a metric, together with d(x, y) = 0 exactly when x = y, and symmetry. For the Euclidean distance it is a theorem. d(x, z) = |x − z| = |(x − y) + (y − z)| ≤ |x − y| + |y − z| = d(x, y) + d(y, z), where the middle step is the triangle inequality for the norm. The same proof works for any normed space. The axiom is what lets open balls form a topology in which the balls are neighborhoods: a ball about a point on the way can be shrunk so that it stays inside the original ball.",
  },
  "tp-homotopy": {
    notation: "H is a continuous map from the product of X with the interval [0, 1] into Y. H₀ means t = 0, and it equals the map f. H₁ means t = 1, and it equals the map g. The parameter t deforms f into g.",
    proof: "The displayed data are the definition of a homotopy from f to g. The relation “there exists a homotopy” is an equivalence relation on maps from X to Y. The homotopy H(x, t) = f(x) shows f is homotopic to itself. If H runs from f to g, then H(x, 1 − t) runs from g to f. If H runs from f to g and K runs from g to h, define a homotopy that follows H for t in [0, 1/2], reparametrized, and follows K for t in [1/2, 1]. It is continuous because the two pieces agree at t = 1/2, where both equal g. It starts at f and ends at h. Homotopic maps induce the same maps on homotopy groups and on homology, which is why the relation is the one those invariants see.",
  },
  "tp-contraction": {
    notation: "T is a map from a metric space to itself. d is the metric. k is a constant. The inequality says T shrinks every distance by at least the factor k. The condition 0 ≤ k < 1 says the shrink is a fixed factor strictly less than 1.",
    proof: "Let the space be complete and nonempty, and pick any x₀. Set x_{n+1} = T xₙ. The contraction gives d(x_{n+1}, xₙ) ≤ kⁿ d(x₁, x₀). For m > n, the triangle inequality yields d(xₘ, xₙ) ≤ (kⁿ + k^{n+1} + ··· + k^{m−1}) d(x₁, x₀) ≤ kⁿ /(1 − k) d(x₁, x₀). The right side tends to 0 as n grows, so (xₙ) is Cauchy. Completeness produces a limit x*. Continuity of T, which follows from the Lipschitz inequality, gives T x* = lim T xₙ = lim x_{n+1} = x*. If T y = y as well, then d(x*, y) = d(T x*, T y) ≤ k d(x*, y), so (1 − k) d(x*, y) = 0. Since k < 1, x* = y. The fixed point exists and is unique, and the iterates of every starting point converge to it.",
  },
};
